$v['client_key']=(string)Illuminate\Support\Str::uuid();$v['body']='Reply';$v['reply_to_id']=$id;ck($c->send(Request::create('/','POST',$v))->getData(true)['status'],'Valid same-conversation reply succeeds');
$cid=$r['data']['conversation_id'];$rows=$c->messages(Request::create('/','POST',['conversation_id'=>$cid]))->getData(true)['data'];ck($rows[0]['reply_preview']==='Hello from QA','Reply preview is server derived');
$v['client_key']=(string)Illuminate\Support\Str::uuid();$v['reply_to_id']=999999999;try{$c->send(Request::create('/','POST',$v));ck(false,'Invalid reply rejected');}catch(Symfony\Component\HttpKernel\Exception\HttpException $e){ck($e->getStatusCode()===422,'Foreign or unavailable reply rejected');}
$v=['receiver_id'=>$b->id,'body'=>'x','message_type'=>'audio'];ck($c->send(Request::create('/','POST',$v))->getData(true)['status']===false,'Audio message type is rejected');
$g=new App\Models\Gifts();$g->title='QA Rose';$g->coin_price=25;$g->image='qa.png';$g->save();$gc=new App\Http\Controllers\GiftController();$gv=['gift_id'=>$g->id,'receiver_id'=>$b->id,'context'=>'chat','expected_coin_price'=>25,'client_key'=>(string)Illuminate\Support\Str::uuid()];$first=$gc->sendGift(Request::create('/','POST',$gv))->getData(true);ck($first['status'],'Gift debits available coins');$retry=$gc->sendGift(Request::create('/','POST',$gv))->getData(true);ck($first['transaction_id']===$retry['transaction_id'] && (int)$a->fresh()->wallet===975,'Gift retry cannot debit twice');
